def closest_pair(points):
    points = sorted(points)

    def dist2(a,b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2

    def solve(p):
        n=len(p)
        if n<=3:
            return min((dist2(p[i],p[j]) for i in range(n) for j in range(i+1,n)), default=float('inf'))

        mid=n//2
        xmid=p[mid][0]
        d=min(solve(p[:mid]),solve(p[mid:]))

        strip=[q for q in p if (q[0]-xmid)**2 < d]
        strip.sort(key=lambda q:q[1])

        for i in range(len(strip)):
            for j in range(i+1,min(i+8,len(strip))):
                d=min(d,dist2(strip[i],strip[j]))
        return d

    return solve(points)

