long long closest(vector<P>& p,int l,int r){
    if(r-l<=3){
        long long ans=LLONG_MAX;
        for(int i=l;i<r;i++) for(int j=i+1;j<r;j++) ans=min(ans,d2(p[i],p[j]));
        return ans;
    }

    int m=(l+r)/2;
    long long d=min(closest(p,l,m),closest(p,m,r));
    long long midx=p[m].first;
    vector<P> strip;

    for(int i=l;i<r;i++)
        if((p[i].first-midx)*(p[i].first-midx)<d) strip.push_back(p[i]);

    sort(strip.begin(),strip.end(),[](P a,P b){return a.second<b.second;});
    for(int i=0;i<strip.size();i++)
        for(int j=i+1;j<strip.size() && j<i+8;j++)
            d=min(d,d2(strip[i],strip[j]));

    return d;
}

