import math

def point_segment_distance(p,a,b):
    vx,vy=b[0]-a[0],b[1]-a[1]
    wx,wy=p[0]-a[0],p[1]-a[1]

    length2=vx*vx+vy*vy
    if length2==0:
        return math.hypot(wx,wy)

    t=(wx*vx+wy*vy)/length2
    t=max(0,min(1,t))

    q=(a[0]+t*vx,a[1]+t*vy)
    return math.hypot(p[0]-q[0],p[1]-q[1])

double pointSegmentDistance(pair<double,double> p,
                              pair<double,double> a,
                              pair<double,double> b) {
    double vx=b.first-a.first, vy=b.second-a.second;
    double wx=p.first-a.first, wy=p.second-a.second;
    double len2=vx*vx+vy*vy;

    if(len2==0) return hypot(wx,wy);

    double t=(wx*vx+wy*vy)/len2;
    t=max(0.0,min(1.0,t));

    double x=a.first+t*vx;
    double y=a.second+t*vy;
    return hypot(p.first-x,p.second-y);
}

static double pointSegmentDistance(double[] p,double[] a,double[] b) {
    double vx=b[0]-a[0], vy=b[1]-a[1];
    double wx=p[0]-a[0], wy=p[1]-a[1];
    double len2=vx*vx+vy*vy;

    if(len2==0) return Math.hypot(wx,wy);

    double t=(wx*vx+wy*vy)/len2;
    t=Math.max(0,Math.min(1,t));

    double x=a[0]+t*vx;
    double y=a[1]+t*vy;
    return Math.hypot(p[0]-x,p[1]-y);
}

